## Secure Implementation

### Tier 1: Critical Fix (5 min)

**Restrict component scanning to trusted packages only**

```java
// SECURE: Restricted component scanning with explicit package boundaries
package com.example.config;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.ComponentScan;

@SpringBootApplication
@ComponentScan(basePackages = {
    "com.example.controllers",
    "com.example.services",
    "com.example.repositories"
    // ✅ SECURE: Explicit allowlist of trusted packages only
    // ✅ Never scan root package "" or user-controlled paths
})
public class SecureApplication {
    public static void main(String[] args) {
        SpringApplication.run(SecureApplication.class, args);
    }
}

// SECURE: Configuration loading with strict validation
package com.example.config;

import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import org.springframework.beans.factory.annotation.Value;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Set;

@RestController
@RequestMapping("/api/config")
public class SecureConfigController {

    // ✅ SECURE: Allowlist of permitted configuration files
    private static final Set<String> ALLOWED_CONFIGS = Set.of(
        "application-dev.properties",
        "application-prod.properties",
        "database.properties"
    );

    @Value("${config.directory}")
    private String configDirectory;

    @PostMapping("/load")
    public ResponseEntity<?> loadConfiguration(@RequestParam String configName) {

        // ✅ SECURE: Strict input validation against allowlist
        if (!ALLOWED_CONFIGS.contains(configName)) {
            return ResponseEntity.badRequest()
                .body("Invalid configuration name");
        }

        // ✅ SECURE: Path traversal prevention
        Path configPath = Paths.get(configDirectory, configName).normalize();
        if (!configPath.startsWith(configDirectory)) {
            return ResponseEntity.badRequest()
                .body("Path traversal detected");
        }

        // ✅ SECURE: Use Spring Environment instead of ClassPathXmlApplicationContext
        try {
            // Load configuration through Spring's PropertySource mechanism
            // This prevents arbitrary bean instantiation
            return ResponseEntity.ok("Configuration loaded safely");
        } catch (Exception e) {
            return ResponseEntity.status(500).body("Failed to load config");
        }
    }
}
