### Tier 2: Essential Defenses (15 min)

**Add classpath scanning restrictions and validation**

```java
// SECURE: Custom ComponentScan filter to block untrusted packages
package com.example.config;

import org.springframework.context.annotation.ComponentScan;
import org.springframework.context.annotation.FilterType;
import org.springframework.stereotype.Component;
import org.springframework.core.type.ClassMetadata;
import org.springframework.core.type.filter.TypeFilter;

import java.util.Set;

@ComponentScan(
    basePackages = {"com.example"},
    excludeFilters = @ComponentScan.Filter(
        type = FilterType.CUSTOM,
        classes = UntrustedPackageFilter.class
    )
)
public class SecureComponentScanConfig {}

@Component
public class UntrustedPackageFilter implements TypeFilter {

    // ✅ Blocklist of dangerous packages
    private static final Set<String> BLOCKED_PACKAGES = Set.of(
        "java.lang",
        "java.io",
        "java.nio",
        "javax.script",
        "groovy.lang",
        "jdk.internal",
        "sun.misc"
    );

    @Override
    public boolean match(MetadataReader reader, MetadataReaderFactory factory) {
        ClassMetadata metadata = reader.getClassMetadata();
        String className = metadata.getClassName();

        // ✅ Block dangerous classes from being scanned
        for (String blocked : BLOCKED_PACKAGES) {
            if (className.startsWith(blocked)) {
                return true; // Exclude this class
            }
        }

        return false;
    }
}

// SECURE: Bean validation on registration
package com.example.config;

import org.springframework.beans.factory.config.BeanFactoryPostProcessor;
import org.springframework.beans.factory.config.ConfigurableListableBeanFactory;
import org.springframework.stereotype.Component;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Component
public class BeanValidationPostProcessor implements BeanFactoryPostProcessor {

    private static final Logger log = LoggerFactory.getLogger(BeanValidationPostProcessor.class);

    private static final Set<String> DANGEROUS_CLASSES = Set.of(
        "java.lang.ProcessBuilder",
        "java.lang.Runtime",
        "javax.script.ScriptEngineManager",
        "groovy.lang.GroovyShell"
    );

    @Override
    public void postProcessBeanFactory(ConfigurableListableBeanFactory beanFactory) {
        String[] beanNames = beanFactory.getBeanDefinitionNames();

        for (String beanName : beanNames) {
            BeanDefinition beanDef = beanFactory.getBeanDefinition(beanName);
            String beanClassName = beanDef.getBeanClassName();

            // ✅ Block dangerous bean types
            if (DANGEROUS_CLASSES.contains(beanClassName)) {
                log.error("SECURITY ALERT: Dangerous bean detected: {} ({})",
                    beanName, beanClassName);
                throw new SecurityException(
                    "Dangerous bean type not allowed: " + beanClassName);
            }
        }
    }
}

// SECURE: Audit logging for bean registration
package com.example.security;

import org.springframework.context.ApplicationListener;
import org.springframework.context.event.ContextRefreshedEvent;
import org.springframework.stereotype.Component;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Component
public class BeanRegistrationAuditor implements ApplicationListener<ContextRefreshedEvent> {

    private static final Logger log = LoggerFactory.getLogger(BeanRegistrationAuditor.class);

    @Override
    public void onApplicationEvent(ContextRefreshedEvent event) {
        // ✅ Log all registered beans for security audit
        String[] beanNames = event.getApplicationContext().getBeanDefinitionNames();
        log.info("Total beans registered: {}", beanNames.length);

        for (String beanName : beanNames) {
            Object bean = event.getApplicationContext().getBean(beanName);
            log.debug("Registered bean: {} ({})",
                beanName, bean.getClass().getName());
        }
    }
}
